\renewcommand{\epigraphflush}{center}

% PDF bookmarks: show section numbers so Appendix A-G are distinguishable from
% Sections 1-7, and list the unnumbered References heading that acl.sty sets
% with \section*. \addcontentsline reuses the anchor \section* already placed.
\hypersetup{bookmarksnumbered=true}
\usepackage{etoolbox}
\patchcmd{\thebibliography}{\list}{\addcontentsline{toc}{section}{References}\list}{}{\PackageError{acl_latex}{Could not add References bookmark}{}}
